#include "surge/chaos_cluster.hpp"
#include <filesystem>
#include <iostream>
#include <stdexcept>
#define CHECK(x) do{if(!(x))throw std::runtime_error("CHECK failed: " #x);}while(0)
int main(){auto root=std::filesystem::temp_directory_path()/"surge-chaos-ledger-tests";std::filesystem::remove_all(root);std::filesystem::create_directories(root);auto path=(root/"chaos.sgj").string();surge::ChaosProvenance p{"test","1","policy-1","2026-11-17T00:00:00Z"};
{surge::ChaosClusterLedger l(path);CHECK(l.open());auto r=l.create("create","ik-create",0,"chaos-1",p);CHECK(r.committed&&r.state_version==1);surge::ChaosMember a{"m1","event-1","NO_STABLE_TOPIC","2026-11-17T00:00:01Z","",p},b{"m2","event-2","CREATIVE_EXPLORATION","2026-11-17T00:00:02Z","",p};CHECK(l.admit_member("m1-op","ik-m1",1,"chaos-1",a).committed);CHECK(l.admit_member("m2-op","ik-m2",2,"chaos-1",b).committed);surge::ChaosAssociation x{"a1","m1","m2",surge::ChaosAssociationType::Analogy,surge::ChaosAssociationStatus::Reviewed,p};CHECK(l.propose_association("a1-op","ik-a1",3,"chaos-1",x).committed);surge::ChaosCluster c;CHECK(l.get("chaos-1",c));CHECK(c.associations.at("a1").status==surge::ChaosAssociationStatus::Provisional);CHECK(l.transition("review","ik-review",4,"chaos-1",surge::ChaosLifecycle::Reviewable,"candidate ready",p).committed);CHECK(l.promote_subset("promote","ik-promote",5,"chaos-1",{{"m1","topic-A"}},p).committed);CHECK(l.get("chaos-1",c));CHECK(c.state_version==6&&c.members.size()==2&&c.promoted_member_targets.size()==1&&c.members.count("m2"));}
{surge::ChaosClusterLedger l(path);CHECK(l.open());surge::ChaosCluster c;CHECK(l.get("chaos-1",c));CHECK(c.members.size()==2&&c.associations.size()==1&&c.promoted_member_targets.at("m1")=="topic-A");auto v=l.state_version();auto stale=l.transition("stale","ik-stale",v-1,"chaos-1",surge::ChaosLifecycle::Dormant,"stale",p);CHECK(!stale.committed&&stale.error=="STATE_VERSION_CONFLICT");auto bad=l.transition("bad","ik-bad",v,"chaos-1",surge::ChaosLifecycle::Open,"backward",p);CHECK(!bad.committed&&bad.error=="CHAOS_LIFECYCLE_TRANSITION_INVALID");}
std::filesystem::remove_all(root);std::cout<<"SURGE Chaos Cluster ledger: persistence, replay, lifecycle, subset promotion passed\n";}
